#define main original_hecbench_main
#include "../histogram-cuda/histogram_compare.cu"
#undef main
#include <vector>
#include <string>
#include <cstdint>
#include <cmath>
#include <chrono>
int main(int argc,char**argv){
const int width=1080,height=1920,n=width*height,repeats=10;bool smem=argc>1&&strcmp(argv[1],"smem")==0;std::string kind=argc>2?argv[2]:"u4";const int channels=kind=="u1"?1:3,bins=channels*256;std::vector<uchar4>rgba(n);uint64_t state=0xabcdef;for(int i=0;i<n;i++){unsigned char*v=reinterpret_cast<unsigned char*>(&rgba[i]);for(int ch=0;ch<4;ch++){state=state*UINT64_C(6364136223846793005)+UINT64_C(1442695040888963407);v[ch]=(state>>32)&255;}}std::vector<uchar1>u1;std::vector<float4>f4;void*input;size_t bytes;if(kind=="u1"){u1.resize(n);for(int i=0;i<n;i++)u1[i].x=(unsigned(rgba[i].x)+rgba[i].y+rgba[i].z)/3;bytes=n;cudaMalloc(&input,bytes);cudaMemcpy(input,u1.data(),bytes,cudaMemcpyHostToDevice);}else if(kind=="f4"){f4.resize(n);for(int i=0;i<n;i++)f4[i]=make_float4(rgba[i].x/256.f,rgba[i].y/256.f,rgba[i].z/256.f,rgba[i].w/256.f);bytes=size_t(n)*16;cudaMalloc(&input,bytes);cudaMemcpy(input,f4.data(),bytes,cudaMemcpyHostToDevice);}else{bytes=size_t(n)*4;cudaMalloc(&input,bytes);cudaMemcpy(input,rgba.data(),bytes,cudaMemcpyHostToDevice);}std::vector<unsigned>gold(bins);if(kind=="u1")HistogramGold<1,256>(u1.data(),width,height,gold.data());else if(kind=="f4")HistogramGold<3,256>(f4.data(),width,height,gold.data());else HistogramGold<3,256>(rgba.data(),width,height,gold.data());std::vector<int>expected(bins+256*bins,0);for(int i=0;i<bins;i++)expected[i]=gold[i];for(int row=0;row<height;row++)for(int col=0;col<width;col++){int pixel=row*width+col,g=(col%512)/32+16*((row%64)/4);for(int channel=0;channel<channels;channel++){int v=kind=="u1"?u1[pixel].x:reinterpret_cast<unsigned char*>(&rgba[pixel])[channel];expected[bins+g*bins+channel*256+v]++;}}unsigned*parts,*out;cudaMalloc(&parts,256*1024*4);cudaMalloc(&out,bins*4);
 auto launch=[&](){if(kind=="u1"){if(smem){histogram_smem_atomics<1024,1,256><<<dim3(16,16),dim3(32,4)>>>((uchar1*)input,width,height,parts);histogram_smem_accum<1024,1,256><<<2,128>>>(parts,256,out);}else{histogram_gmem_atomics<1024,1,256><<<dim3(16,16),dim3(32,4)>>>((uchar1*)input,width,height,parts);histogram_gmem_accum<1024,1,256><<<2,128>>>(parts,256,out);}}else if(kind=="f4"){if(smem){histogram_smem_atomics<1024,3,256><<<dim3(16,16),dim3(32,4)>>>((float4*)input,width,height,parts);histogram_smem_accum<1024,3,256><<<6,128>>>(parts,256,out);}else{histogram_gmem_atomics<1024,3,256><<<dim3(16,16),dim3(32,4)>>>((float4*)input,width,height,parts);histogram_gmem_accum<1024,3,256><<<6,128>>>(parts,256,out);}}else{if(smem){histogram_smem_atomics<1024,3,256><<<dim3(16,16),dim3(32,4)>>>((uchar4*)input,width,height,parts);histogram_smem_accum<1024,3,256><<<6,128>>>(parts,256,out);}else{histogram_gmem_atomics<1024,3,256><<<dim3(16,16),dim3(32,4)>>>((uchar4*)input,width,height,parts);histogram_gmem_accum<1024,3,256><<<6,128>>>(parts,256,out);}}};launch();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;
 bool allok=true;for(int trial=1;trial<=5;trial++){
 cudaMemset(parts,0,256*1024*4);cudaMemset(out,0,bins*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeats;j++)launch();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeats;
 std::vector<unsigned>po(256*1024),ho(bins);cudaMemcpy(po.data(),parts,po.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(ho.data(),out,bins*4,cudaMemcpyDeviceToHost);std::vector<int>got;got.reserve(expected.size());for(auto v:ho)got.push_back(v);for(int group=0;group<256;group++)for(int i=0;i<bins;i++)got.push_back(po[group*1024+i]);
 bool ok=status==cudaSuccess;double error=0,relative=0;for(size_t j=0;j<got.size();j++){double e=fabs((double)got[j]-expected[j]);error=fmax(error,e);relative=fmax(relative,e/fmax(fabs((double)expected[j]),1e-300));ok&=std::isfinite((double)got[j])&&e<=0;}allok&=ok;
 char filename[80];snprintf(filename,sizeof(filename),"output_trial%d.bin",trial);FILE*f=fopen(filename,"wb");if(!f)return 5;fwrite(got.data(),sizeof(int),got.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size(),error,relative,repeats,filename,got.size());
 }return allok?0:1;
}
